#### 1. Retry Policy Configuration

**Polly Implementation (.NET)**:

```csharp
using Polly;
using Polly.Retry;
using Microsoft.Extensions.Logging;

public class RetryPolicyFactory
{
    private readonly ILogger<RetryPolicyFactory> _logger;

    public RetryPolicyFactory(ILogger<RetryPolicyFactory> logger)
    {
        _logger = logger;
    }

    /// <summary>
    /// Creates retry policy with exponential backoff for transient HTTP errors
    /// </summary>
    public AsyncRetryPolicy<HttpResponseMessage> CreateHttpRetryPolicy()
    {
        return Policy
            .HandleResult<HttpResponseMessage>(r =>
                // Retry on transient HTTP status codes
                r.StatusCode == HttpStatusCode.RequestTimeout ||           // 408
                r.StatusCode == (HttpStatusCode)429 ||                     // 429 Too Many Requests
                r.StatusCode == HttpStatusCode.InternalServerError ||      // 500
                r.StatusCode == HttpStatusCode.BadGateway ||               // 502
                r.StatusCode == HttpStatusCode.ServiceUnavailable ||       // 503
                r.StatusCode == HttpStatusCode.GatewayTimeout)             // 504
            .Or<HttpRequestException>()     // Network failures
            .Or<TaskCanceledException>()    // Timeouts
            .WaitAndRetryAsync(
                retryCount: 5,
                sleepDurationProvider: (retryAttempt, context) =>
                    CalculateExponentialBackoffWithJitter(retryAttempt),
                onRetry: (outcome, timespan, retryAttempt, context) =>
                {
                    var statusCode = outcome.Result?.StatusCode.ToString() ?? "Exception";
                    _logger.LogWarning(
                        "Retry attempt {RetryAttempt} after {Delay}ms for {StatusCode}. CorrelationId: {CorrelationId}",
                        retryAttempt,
                        timespan.TotalMilliseconds,
                        statusCode,
                        context["CorrelationId"]);
                });
    }

    /// <summary>
    /// Exponential backoff: 1s, 2s, 4s, 8s, 16s with ±20% jitter
    /// </summary>
    private TimeSpan CalculateExponentialBackoffWithJitter(int retryAttempt)
    {
        var baseDelay = TimeSpan.FromSeconds(Math.Pow(2, retryAttempt - 1));
        var jitter = TimeSpan.FromMilliseconds(
            Random.Shared.Next(-200, 200));  // ±20% jitter

        return baseDelay + jitter;
    }
}
```

**Resilience4j Implementation (Java)**:

```java
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import io.github.resilience4j.retry.RetryRegistry;
import org.springframework.stereotype.Component;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.ResourceAccessException;

import java.time.Duration;
import java.util.function.Predicate;

@Component
public class RetryPolicyFactory {

    /**
     * Creates retry policy with exponential backoff for transient HTTP errors
     */
    public Retry createHttpRetryPolicy() {
        RetryConfig config = RetryConfig.custom()
            .maxAttempts(5)
            .waitDuration(Duration.ofSeconds(1))  // Base delay
            .intervalFunction(IntervalFunction.ofExponentialRandomBackoff(
                Duration.ofSeconds(1),   // Initial interval
                2.0,                     // Multiplier
                Duration.ofSeconds(30)   // Max interval
            ))
            .retryOnResult(this::isTransientHttpError)
            .retryExceptions(
                HttpServerErrorException.class,   // 5xx errors
                ResourceAccessException.class)     // Network failures
            .ignoreExceptions(
                IllegalArgumentException.class)    // Don't retry validation errors
            .build();

        RetryRegistry registry = RetryRegistry.of(config);
        Retry retry = registry.retry("httpClientRetry");

        // Event listeners for observability
        retry.getEventPublisher()
            .onRetry(event -> log.warn(
                "Retry attempt {} after {}ms for {}. CorrelationId: {}",
                event.getNumberOfRetryAttempts(),
                event.getWaitInterval().toMillis(),
                event.getLastThrowable().getMessage(),
                MDC.get("correlationId")));

        return retry;
    }

    /**
     * Determines if HTTP status code indicates transient error
     */
    private boolean isTransientHttpError(Object response) {
        if (response instanceof ResponseEntity) {
            HttpStatus status = ((ResponseEntity<?>) response).getStatusCode();
            return status == HttpStatus.REQUEST_TIMEOUT ||           // 408
                   status == HttpStatus.TOO_MANY_REQUESTS ||         // 429
                   status == HttpStatus.INTERNAL_SERVER_ERROR ||     // 500
                   status == HttpStatus.BAD_GATEWAY ||               // 502
                   status == HttpStatus.SERVICE_UNAVAILABLE ||       // 503
                   status == HttpStatus.GATEWAY_TIMEOUT;             // 504
        }
        return false;
    }
}
```

