#### 3. Transient Fault Detection

**Decision Logic:**

```csharp
public class TransientFaultDetector
{
    /// <summary>
    /// Determines if exception represents transient fault worth retrying
    /// </summary>
    public static bool IsTransientFault(Exception exception)
    {
        return exception switch
        {
            // Network-level transient failures
            HttpRequestException httpEx when
                httpEx.InnerException is SocketException => true,

            // Timeout indicates potential transient overload
            TaskCanceledException => true,
            TimeoutException => true,

            // Database transient errors (SQL Server)
            SqlException sqlEx when IsTransientSqlError(sqlEx.Number) => true,

            // Azure SQL throttling
            SqlException sqlEx when sqlEx.Number == 40613 => true,

            // Non-transient failures - don't retry
            ArgumentException => false,
            ArgumentNullException => false,
            InvalidOperationException => false,
            UnauthorizedAccessException => false,

            _ => false
        };
    }

    /// <summary>
    /// SQL Server transient error codes
    /// See: https://docs.microsoft.com/en-us/azure/sql-database/sql-database-develop-error-messages
    /// </summary>
    private static bool IsTransientSqlError(int errorNumber)
    {
        return errorNumber switch
        {
            -2 => true,      // Timeout
            -1 => true,      // Connection broken
            2 => true,       // Network error
            53 => true,      // Connection initialization error
            64 => true,      // Server error during login
            233 => true,     // Connection initialization error
            10053 => true,   // Transport-level error
            10054 => true,   // Forcibly closed by remote host
            10060 => true,   // Network timeout
            40197 => true,   // Service error processing request
            40501 => true,   // Service is busy
            40613 => true,   // Database unavailable
            49918 => true,   // Cannot process request (insufficient resources)
            49919 => true,   // Cannot process create/update request
            49920 => true,   // Cannot process request (too many operations)
            _ => false
        };
    }

    /// <summary>
    /// Determines if HTTP status code is transient
    /// </summary>
    public static bool IsTransientHttpStatus(HttpStatusCode statusCode)
    {
        return statusCode switch
        {
            HttpStatusCode.RequestTimeout => true,              // 408
            (HttpStatusCode)429 => true,                        // 429 Too Many Requests
            HttpStatusCode.InternalServerError => true,         // 500
            HttpStatusCode.BadGateway => true,                  // 502
            HttpStatusCode.ServiceUnavailable => true,          // 503
            HttpStatusCode.GatewayTimeout => true,              // 504

            // Non-transient - don't retry
            HttpStatusCode.BadRequest => false,                 // 400
            HttpStatusCode.Unauthorized => false,               // 401
            HttpStatusCode.Forbidden => false,                  // 403
            HttpStatusCode.NotFound => false,                   // 404
            HttpStatusCode.MethodNotAllowed => false,           // 405
            HttpStatusCode.Conflict => false,                   // 409

            _ => false
        };
    }
}
```

