#### 4. Idempotency Implementation

**Idempotency Key Pattern for Safe Retries:**

```csharp
public class IdempotentClaimSubmissionService
{
    private readonly IClaimRepository _claimRepository;
    private readonly IDistributedCache _cache;  // Redis

    /// <summary>
    /// Submit claim with idempotency guarantee - safe to retry
    /// </summary>
    public async Task<ClaimSubmissionResult> SubmitClaimAsync(
        Claim claim,
        string idempotencyKey)
    {
        // Check if this request was already processed
        var cachedResult = await _cache.GetStringAsync($"claim:idempotency:{idempotencyKey}");
        if (cachedResult != null)
        {
            // Return cached result - request already processed
            return JsonSerializer.Deserialize<ClaimSubmissionResult>(cachedResult);
        }

        // Process claim submission
        var result = await ProcessClaimSubmissionAsync(claim);

        // Cache result with 24-hour TTL (idempotency window)
        await _cache.SetStringAsync(
            $"claim:idempotency:{idempotencyKey}",
            JsonSerializer.Serialize(result),
            new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(24)
            });

        return result;
    }

    /// <summary>
    /// Generate idempotency key for claim submission
    /// </summary>
    public static string GenerateIdempotencyKey(Guid claimId, Guid userId)
    {
        return $"{claimId}:{userId}:{DateTime.UtcNow:yyyyMMdd}";
    }
}
```

