        .CreateHistogram(
            "retry_duration_seconds",
            "Duration of retry attempts including backoff time",
            new HistogramConfiguration
            {
                LabelNames = new[] { "service", "operation" },
                Buckets = Histogram.ExponentialBuckets(0.1, 2, 10)  // 0.1s to 51.2s
            });

    public static void RecordRetryAttempt(string service, string operation, int attemptNumber)
