    }

    public static void RecordRetrySuccess(string service, string operation, int attemptNumber)
    {
        RetrySuccessTotal.WithLabels(service, operation, attemptNumber.ToString()).Inc();
    }

    public static void RecordRetryExhausted(string service, string operation)
    {
        RetryExhaustedTotal.WithLabels(service, operation).Inc();
    }

    public static IDisposable MeasureRetryDuration(string service, string operation)
    {
        return RetryDuration.WithLabels(service, operation).NewTimer();
    }
}
