### Phase 2: Configure Retry Policy

**Step 1: Define Retry Configuration**

```csharp
// appsettings.json - Retry configuration
{
  "RetryPolicy": {
    "MaxAttempts": 5,
    "BaseDelaySeconds": 1,
    "MaxDelaySeconds": 30,
    "JitterPercentage": 20,
    "TransientStatusCodes": [408, 429, 500, 502, 503, 504]
  }
}
```

**Step 2: Create Retry Policy Factory**

```csharp
using Microsoft.Extensions.Options;
using Polly;
using Polly.Retry;

public class RetryPolicyOptions
{
    public int MaxAttempts { get; set; } = 5;
    public double BaseDelaySeconds { get; set; } = 1.0;
    public double MaxDelaySeconds { get; set; } = 30.0;
    public int JitterPercentage { get; set; } = 20;
    public int[] TransientStatusCodes { get; set; } = { 408, 429, 500, 502, 503, 504 };
}

public class RetryPolicyFactory
{
    private readonly RetryPolicyOptions _options;
    private readonly ILogger<RetryPolicyFactory> _logger;

    public RetryPolicyFactory(
        IOptions<RetryPolicyOptions> options,
        ILogger<RetryPolicyFactory> logger)
    {
        _options = options.Value;
        _logger = logger;
    }

    public AsyncRetryPolicy<HttpResponseMessage> CreatePolicy()
    {
        return Policy
            .HandleResult<HttpResponseMessage>(r =>
                _options.TransientStatusCodes.Contains((int)r.StatusCode))
            .Or<HttpRequestException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(
                retryCount: _options.MaxAttempts,
                sleepDurationProvider: (retryAttempt, context) =>
                {
                    var baseDelay = TimeSpan.FromSeconds(
                        Math.Pow(2, retryAttempt - 1) * _options.BaseDelaySeconds);

                    // Apply max delay cap
                    if (baseDelay.TotalSeconds > _options.MaxDelaySeconds)
                        baseDelay = TimeSpan.FromSeconds(_options.MaxDelaySeconds);

                    // Add jitter (±20%)
                    var jitterMs = Random.Shared.Next(
                        -(int)(baseDelay.TotalMilliseconds * _options.JitterPercentage / 100),
                        (int)(baseDelay.TotalMilliseconds * _options.JitterPercentage / 100));

                    return baseDelay + TimeSpan.FromMilliseconds(jitterMs);
                },
                onRetry: (outcome, timespan, retryAttempt, context) =>
                {
                    _logger.LogWarning(
                        "Retry {RetryAttempt}/{MaxAttempts} after {DelayMs}ms for {ServiceName}.{OperationName}. " +
                        "StatusCode: {StatusCode}, CorrelationId: {CorrelationId}",
                        retryAttempt,
                        _options.MaxAttempts,
                        timespan.TotalMilliseconds,
                        context.GetValueOrDefault("ServiceName"),
                        context.GetValueOrDefault("OperationName"),
                        outcome.Result?.StatusCode.ToString() ?? outcome.Exception?.GetType().Name,
                        context.GetValueOrDefault("CorrelationId"));

                    // Record metrics
                    RetryMetrics.RecordRetryAttempt(
                        context["ServiceName"].ToString(),
                        context["OperationName"].ToString(),
                        retryAttempt);
                });
    }
}
```

