### Phase 3: Implement Transient Fault Detection

**Comprehensive Fault Detection Predicate:**

```csharp
public class TransientFaultDetector
{
    /// <summary>
    /// Evaluates if HTTP response represents transient fault
    /// </summary>
    public static bool IsTransientHttpError(HttpResponseMessage response)
    {
        // Transient HTTP status codes
        if (response.StatusCode == HttpStatusCode.RequestTimeout ||           // 408
            response.StatusCode == (HttpStatusCode)429 ||                     // 429
            response.StatusCode == HttpStatusCode.InternalServerError ||      // 500
            response.StatusCode == HttpStatusCode.BadGateway ||               // 502
            response.StatusCode == HttpStatusCode.ServiceUnavailable ||       // 503
            response.StatusCode == HttpStatusCode.GatewayTimeout)             // 504
        {
            return true;
        }

        // Check Retry-After header (indicates temporary condition)
        if (response.Headers.RetryAfter != null)
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// Evaluates if exception represents transient fault
    /// </summary>
    public static bool IsTransientException(Exception exception)
    {
        return exception switch
        {
            // HTTP-related transient failures
            HttpRequestException httpEx when
                httpEx.InnerException is SocketException ||
                httpEx.InnerException is IOException => true,

            // Timeout exceptions
            TaskCanceledException => true,
            TimeoutException => true,
            OperationCanceledException cancelEx when
                cancelEx.CancellationToken.IsCancellationRequested == false => true,

            // SQL Server transient errors
            SqlException sqlEx when IsTransientSqlError(sqlEx) => true,

            // Azure Service Bus transient errors
            ServiceBusException sbEx when
                sbEx.IsTransient => true,

            _ => false
        };
    }

    private static bool IsTransientSqlError(SqlException exception)
    {
        // See: https://docs.microsoft.com/azure/azure-sql/database/troubleshoot-common-errors-issues
        return exception.Errors
            .Cast<SqlError>()
            .Any(error => error.Number switch
            {
                -2 or -1 or 2 or 53 or 64 or 233 or 10053 or 10054 or 10060
                    or 40197 or 40501 or 40613 or 49918 or 49919 or 49920 => true,
                _ => false
            });
    }
}
```

