    /// <summary>
    /// Submit claim with idempotency guarantee
    /// </summary>
    public async Task<ClaimSubmissionResult> SubmitClaimAsync(
        Claim claim,
        Guid userId,
        CancellationToken cancellationToken = default)
    {
        // Generate idempotency key
        var idempotencyKey = IdempotencyKeyGenerator.GenerateKey(
            claim.ClaimId, userId, claim);

        // Check for duplicate request
        var cachedResult = await GetCachedResultAsync(idempotencyKey, cancellationToken);
        if (cachedResult != null)
        {
            _logger.LogInformation(
                "Idempotent request detected for claim {ClaimId}. Returning cached result. Key: {IdempotencyKey}",
                claim.ClaimId,
                idempotencyKey);

            return cachedResult;
        }

        // Process claim submission
        var result = await ProcessClaimAsync(claim, cancellationToken);

        // Cache result for 24 hours (idempotency window)
        await CacheResultAsync(idempotencyKey, result, cancellationToken);

        return result;
    }

    private async Task<ClaimSubmissionResult> GetCachedResultAsync(
        string idempotencyKey,
        CancellationToken cancellationToken)
    {
        var cachedJson = await _cache.GetStringAsync(idempotencyKey, cancellationToken);

        return cachedJson != null
            ? JsonSerializer.Deserialize<ClaimSubmissionResult>(cachedJson)
            : null;
    }

    private async Task CacheResultAsync(
        string idempotencyKey,
        ClaimSubmissionResult result,
        CancellationToken cancellationToken)
    {
        var json = JsonSerializer.Serialize(result);

        await _cache.SetStringAsync(
            idempotencyKey,
            json,
            new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(24)
            },
            cancellationToken);
    }
}
