### Phase 5: Add Monitoring and Observability

**Step 1: Define Metrics**

```csharp
using Prometheus;

public static class RetryMetrics
{
    // Counter: Total retry attempts
    private static readonly Counter RetryAttemptsTotal = Metrics.CreateCounter(
        "retry_attempts_total",
        "Total number of retry attempts",
        new CounterConfiguration
        {
            LabelNames = new[] { "service", "operation", "attempt", "result" }
        });

    // Counter: Requests that exhausted retries
    private static readonly Counter RetryExhaustedTotal = Metrics.CreateCounter(
        "retry_exhausted_total",
        "Number of requests that exhausted all retry attempts",
        new CounterConfiguration
        {
            LabelNames = new[] { "service", "operation", "status_code" }
        });

    // Histogram: Retry duration
    private static readonly Histogram RetryDurationSeconds = Metrics.CreateHistogram(
        "retry_duration_seconds",
        "Duration of retry cycle including backoff time",
        new HistogramConfiguration
        {
            LabelNames = new[] { "service", "operation" },
            Buckets = Histogram.ExponentialBuckets(0.1, 2, 10)  // 0.1s to 102.4s
        });

    // Gauge: Current retry success rate
    private static readonly Gauge RetrySuccessRate = Metrics.CreateGauge(
        "retry_success_rate",
        "Success rate of retry attempts (sliding window)",
        new GaugeConfiguration
        {
            LabelNames = new[] { "service", "operation" }
        });

    public static void RecordRetryAttempt(string service, string operation, int attempt, bool success)
    {
        RetryAttemptsTotal
            .WithLabels(service, operation, attempt.ToString(), success ? "success" : "failure")
            .Inc();
    }

    public static void RecordRetryExhausted(string service, string operation, string statusCode)
    {
        RetryExhaustedTotal
            .WithLabels(service, operation, statusCode)
            .Inc();
    }

    public static IDisposable MeasureRetryDuration(string service, string operation)
    {
        return RetryDurationSeconds
            .WithLabels(service, operation)
            .NewTimer();
    }

    public static void UpdateSuccessRate(string service, string operation, double rate)
    {
        RetrySuccessRate
            .WithLabels(service, operation)
            .Set(rate);
    }
}
```

**Step 2: Integrate Metrics with Retry Policy**

```csharp
public AsyncRetryPolicy<HttpResponseMessage> CreateInstrumentedPolicy(
    string serviceName,
    string operationName)
{
    return Policy
        .HandleResult<HttpResponseMessage>(r => IsTransientHttpError(r))
        .Or<HttpRequestException>()
        .WaitAndRetryAsync(
            retryCount: 5,
            sleepDurationProvider: (attempt, ctx) => CalculateBackoff(attempt),
            onRetry: (outcome, timespan, attempt, context) =>
            {
                // Log retry attempt
                _logger.LogWarning(
                    "Retry {Attempt}/5 for {Service}.{Operation} after {Delay}ms. Status: {Status}",
                    attempt, serviceName, operationName,
                    timespan.TotalMilliseconds,
                    outcome.Result?.StatusCode.ToString() ?? outcome.Exception?.GetType().Name);

                // Record metrics
                bool success = outcome.Result?.IsSuccessStatusCode ?? false;
                RetryMetrics.RecordRetryAttempt(serviceName, operationName, attempt, success);

                // Record exhaustion on final attempt
                if (attempt == 5 && !success)
                {
                    var statusCode = outcome.Result?.StatusCode.ToString() ?? "Exception";
                    RetryMetrics.RecordRetryExhausted(serviceName, operationName, statusCode);
                }
            });
}
```

