    private readonly HttpClient _httpClient;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;

    public RetryPolicyTests()
    {
        _mockServer = WireMockServer.Start();
        _httpClient = new HttpClient { BaseAddress = new Uri(_mockServer.Url) };

        var factory = new RetryPolicyFactory(
            Options.Create(new RetryPolicyOptions()),
            new NullLogger<RetryPolicyFactory>());
        _retryPolicy = factory.CreatePolicy();
    }

    [Fact]
    public async Task Retry_Should_Succeed_After_Transient_503_Errors()
    {
        // Arrange: First 2 requests return 503, third succeeds
        _mockServer
            .Given(Request.Create().WithPath("/eligibility").UsingGet())
            .InScenario("RetryScenario")
            .WillSetStateTo("Attempt1")
            .RespondWith(Response.Create()
                .WithStatusCode(503)
                .WithBody("Service Unavailable"));

        _mockServer
            .Given(Request.Create().WithPath("/eligibility").UsingGet())
            .InScenario("RetryScenario")
            .WhenStateIs("Attempt1")
            .WillSetStateTo("Attempt2")
            .RespondWith(Response.Create()
                .WithStatusCode(503)
                .WithBody("Service Unavailable"));

        _mockServer
            .Given(Request.Create().WithPath("/eligibility").UsingGet())
            .InScenario("RetryScenario")
            .WhenStateIs("Attempt2")
            .RespondWith(Response.Create()
                .WithStatusCode(200)
                .WithBody("{\"isEligible\": true}"));

        // Act
        var stopwatch = Stopwatch.StartNew();
        var response = await _retryPolicy.ExecuteAsync(async () =>
            await _httpClient.GetAsync("/eligibility"));
        stopwatch.Stop();

        // Assert
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal(3, _mockServer.LogEntries.Count());  // 3 attempts

        // Verify exponential backoff timing (1s + 2s = ~3s total)
        Assert.InRange(stopwatch.ElapsedMilliseconds, 2500, 3500);
    }

    [Fact]
    public async Task Retry_Should_Exhaust_After_Max_Attempts()
    {
        // Arrange: All requests return 503
        _mockServer
            .Given(Request.Create().WithPath("/eligibility").UsingGet())
            .RespondWith(Response.Create()
                .WithStatusCode(503)
                .WithBody("Service Unavailable"));

        // Act & Assert
        var response = await _retryPolicy.ExecuteAsync(async () =>
            await _httpClient.GetAsync("/eligibility"));

        Assert.Equal(HttpStatusCode.ServiceUnavailable, response.StatusCode);
        Assert.Equal(5, _mockServer.LogEntries.Count());  // 5 attempts (initial + 4 retries)
    }

    [Fact]
    public async Task Retry_Should_Not_Retry_400_BadRequest()
    {
        // Arrange
        _mockServer
            .Given(Request.Create().WithPath("/eligibility").UsingGet())
            .RespondWith(Response.Create()
                .WithStatusCode(400)
                .WithBody("Bad Request"));

        // Act
        var response = await _retryPolicy.ExecuteAsync(async () =>
            await _httpClient.GetAsync("/eligibility"));

        // Assert: No retries for 400 (non-transient)
        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        Assert.Single(_mockServer.LogEntries);  // Only 1 attempt
    }
}
