**Retry Policy Configuration:**

```csharp
using Polly;
using Polly.CircuitBreaker;
using Polly.Wrap;
using Microsoft.Extensions.Logging;

public class EligibilityServiceClient
{
    private readonly HttpClient _httpClient;
    private readonly AsyncPolicyWrap<HttpResponseMessage> _resiliencePolicy;
    private readonly ILogger<EligibilityServiceClient> _logger;

    public EligibilityServiceClient(
        HttpClient httpClient,
        ILogger<EligibilityServiceClient> logger)
    {
        _httpClient = httpClient;
        _logger = logger;

        // Retry Policy: 5 attempts with exponential backoff
        var retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r =>
                r.StatusCode == HttpStatusCode.ServiceUnavailable ||      // 503
                r.StatusCode == (HttpStatusCode)429 ||                    // 429 Too Many Requests
                r.StatusCode == HttpStatusCode.RequestTimeout ||          // 408
                r.StatusCode == HttpStatusCode.GatewayTimeout)            // 504
            .Or<HttpRequestException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(
                retryCount: 5,
                sleepDurationProvider: (attempt, context) =>
                {
                    // Exponential backoff: 1s, 2s, 4s, 8s, 16s
                    var baseDelay = TimeSpan.FromSeconds(Math.Pow(2, attempt - 1));

                    // Add jitter (±20%)
                    var jitter = TimeSpan.FromMilliseconds(
                        Random.Shared.Next(-200, 200));

                    return baseDelay + jitter;
                },
                onRetry: (outcome, timespan, attempt, context) =>
                {
                    var claimId = context.GetValueOrDefault("ClaimId");
                    var statusCode = outcome.Result?.StatusCode.ToString() ??
                                   outcome.Exception?.GetType().Name;

                    _logger.LogWarning(
                        "Eligibility check retry {Attempt}/5 for claim {ClaimId} after {DelayMs}ms. " +
                        "Status: {StatusCode}, CorrelationId: {CorrelationId}",
                        attempt,
                        claimId,
                        timespan.TotalMilliseconds,
                        statusCode,
                        context["CorrelationId"]);

                    // Record metrics
                    RetryMetrics.RecordRetryAttempt(
                        "ClaimsAdjudication",
                        "CheckEligibility",
                        attempt,
                        outcome.Result?.IsSuccessStatusCode ?? false);
                });

        // Circuit Breaker Policy: Open after 50% failures in 1 minute
        var circuitBreakerPolicy = Policy
            .HandleResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
            .Or<HttpRequestException>()
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 10,
                durationOfBreak: TimeSpan.FromSeconds(60),
                onBreak: (outcome, duration) =>
                {
                    _logger.LogError(
                        "Circuit breaker OPENED for EligibilityService. " +
                        "Breaking for {DurationSeconds}s due to {FailureCount} consecutive failures.",
                        duration.TotalSeconds,
                        10);
                },
                onReset: () =>
                {
                    _logger.LogInformation(
                        "Circuit breaker CLOSED for EligibilityService. Resuming normal operations.");
                });

        // Combine policies: Circuit Breaker wraps Retry
        _resiliencePolicy = Policy.WrapAsync(circuitBreakerPolicy, retryPolicy);
    }

    /// <summary>
    /// Check member eligibility with automatic retry on transient failures
    /// </summary>
    public async Task<EligibilityResponse> CheckEligibilityAsync(
        Guid claimId,
        string memberId,
        DateTime serviceDate,
        CancellationToken cancellationToken = default)
    {
        var context = new Context
        {
            ["ClaimId"] = claimId,
            ["CorrelationId"] = Activity.Current?.Id ?? Guid.NewGuid().ToString()
        };

        var stopwatch = Stopwatch.StartNew();

        try
        {
            var response = await _resiliencePolicy.ExecuteAsync(
                async (ctx, ct) =>
                {
                    var request = new HttpRequestMessage(HttpMethod.Get,
                        $"https://eligibility-api.gainwell.com/v1/members/{memberId}/eligibility" +
                        $"?serviceDate={serviceDate:yyyy-MM-dd}");

                    request.Headers.Add("X-Correlation-Id", ctx["CorrelationId"].ToString());

                    return await _httpClient.SendAsync(request, ct);
                },
                context,
                cancellationToken);

            response.EnsureSuccessStatusCode();

            var eligibility = await response.Content.ReadFromJsonAsync<EligibilityResponse>(
                cancellationToken: cancellationToken);

            _logger.LogInformation(
                "Eligibility check succeeded for claim {ClaimId} in {DurationMs}ms. IsEligible: {IsEligible}",
                claimId,
                stopwatch.ElapsedMilliseconds,
                eligibility.IsEligible);

            return eligibility;
        }
        catch (BrokenCircuitException ex)
        {
            _logger.LogError(ex,
                "Eligibility check failed for claim {ClaimId} - Circuit breaker OPEN",
                claimId);

            throw new ServiceUnavailableException(
                "Eligibility service temporarily unavailable. Circuit breaker open.", ex);
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex,
                "Eligibility check exhausted retries for claim {ClaimId} after {DurationMs}ms",
                claimId,
                stopwatch.ElapsedMilliseconds);

            RetryMetrics.RecordRetryExhausted("ClaimsAdjudication", "CheckEligibility");

            throw new EligibilityCheckFailedException(
                $"Failed to check eligibility after {5} retry attempts", ex);
        }
    }
}
