**Intelligent Retry with Rate Limit Detection:**

```csharp
using Polly;
using Polly.RateLimit;

public class LicenseVerificationClient
{
    private readonly HttpClient _httpClient;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;
    private readonly ILogger<LicenseVerificationClient> _logger;

    public LicenseVerificationClient(
        HttpClient httpClient,
        ILogger<LicenseVerificationClient> logger)
    {
        _httpClient = httpClient;
        _logger = logger;

        _retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r =>
                r.StatusCode == (HttpStatusCode)429 ||                    // Rate limited
                r.StatusCode == HttpStatusCode.ServiceUnavailable ||      // 503
                r.StatusCode == HttpStatusCode.GatewayTimeout)            // 504
            .WaitAndRetryAsync(
                retryCount: 5,
                sleepDurationProvider: (attempt, outcome, context) =>
                {
                    // Check for Retry-After header (RFC 7231)
                    if (outcome.Result?.Headers?.RetryAfter != null)
                    {
                        if (outcome.Result.Headers.RetryAfter.Delta.HasValue)
                        {
                            var retryAfter = outcome.Result.Headers.RetryAfter.Delta.Value;

                            _logger.LogWarning(
                                "Rate limited. Respecting Retry-After header: {RetryAfterSeconds}s",
                                retryAfter.TotalSeconds);

                            // Add small jitter to Retry-After value
                            var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000));
                            return retryAfter + jitter;
                        }
                    }

                    // Fallback to exponential backoff if no Retry-After header
                    var baseDelay = TimeSpan.FromSeconds(Math.Pow(2, attempt));
                    var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(-500, 500));
                    return baseDelay + jitter;
                },
                onRetry: (outcome, timespan, attempt, context) =>
                {
                    var providerId = context["ProviderId"];
                    var licenseNumber = context["LicenseNumber"];

                    _logger.LogWarning(
                        "License verification retry {Attempt}/5 for provider {ProviderId} " +
                        "after {DelaySeconds}s. Status: {StatusCode}",
                        attempt,
                        providerId,
                        timespan.TotalSeconds,
                        outcome.Result?.StatusCode);
                });
    }

    /// <summary>
    /// Verify provider license with intelligent rate limit handling
    /// </summary>
    public async Task<LicenseStatus> VerifyLicenseAsync(
        Guid providerId,
        string licenseNumber,
        string state,
        CancellationToken cancellationToken = default)
    {
        var context = new Context
        {
            ["ProviderId"] = providerId,
            ["LicenseNumber"] = licenseNumber,
            ["State"] = state
        };

        var response = await _retryPolicy.ExecuteAsync(
            async (ctx, ct) =>
            {
                var request = new HttpRequestMessage(HttpMethod.Get,
                    $"https://{state.ToLower()}medicalboard.gov/api/v2/verify/{licenseNumber}");

                request.Headers.Add("X-API-Key", GetApiKey(state));

                return await _httpClient.SendAsync(request, ct);
            },
            context,
            cancellationToken);

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<LicenseStatus>(
            cancellationToken: cancellationToken);
    }

    private string GetApiKey(string state)
    {
        // Retrieve state-specific API key from configuration
        return _configuration[$"StateMedicalBoards:{state}:ApiKey"];
    }
}
