**Fast Retry with Constant Short Backoff:**

```csharp
using Polly;

public class PharmacyPosClient
{
    private readonly HttpClient _httpClient;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;
    private readonly ILogger<PharmacyPosClient> _logger;

    public PharmacyPosClient(
        HttpClient httpClient,
        ILogger<PharmacyPosClient> logger)
    {
        _httpClient = httpClient;
        _logger = logger;

        // Retry Policy: 3 attempts with 500ms constant backoff (stays within 10s window)
        _retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r =>
                r.StatusCode == HttpStatusCode.RequestTimeout ||          // 408
                r.StatusCode == HttpStatusCode.GatewayTimeout ||          // 504
                r.StatusCode == HttpStatusCode.ServiceUnavailable)        // 503
            .Or<TimeoutException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(
                retryCount: 3,  // Limited to 3 to stay within 10s window
                sleepDurationProvider: (attempt) =>
                {
                    // Constant 500ms backoff (not exponential)
                    // Total time: 3 attempts × 3s timeout + 3 retries × 0.5s = 10.5s
                    return TimeSpan.FromMilliseconds(500);
                },
                onRetry: (outcome, timespan, attempt, context) =>
                {
                    var transactionId = context["TransactionId"];

                    _logger.LogWarning(
                        "NCPDP transaction retry {Attempt}/3 for {TransactionId} after {DelayMs}ms",
                        attempt,
                        transactionId,
                        timespan.TotalMilliseconds);
                });
    }

    /// <summary>
    /// Submit NCPDP transaction with idempotency guarantee
    /// </summary>
    public async Task<NcpdpResponse> SubmitTransactionAsync(
        NcpdpTransaction transaction,
        CancellationToken cancellationToken = default)
    {
        // Generate idempotency key to prevent duplicate dispense
        var idempotencyKey = GenerateIdempotencyKey(transaction);

        // Check cache for duplicate request
        var cachedResponse = await GetCachedResponseAsync(idempotencyKey, cancellationToken);
        if (cachedResponse != null)
        {
            _logger.LogInformation(
                "Returning cached NCPDP response for transaction {TransactionId}. " +
                "Duplicate request detected via idempotency key.",
                transaction.TransactionId);

            return cachedResponse;
        }

        var context = new Context
        {
            ["TransactionId"] = transaction.TransactionId,
            ["PrescriptionNumber"] = transaction.PrescriptionNumber
        };

        // Apply 8-second timeout (leaves 2s buffer within 10s window for 3 retries)
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        cts.CancelAfter(TimeSpan.FromSeconds(8));

        var stopwatch = Stopwatch.StartNew();

        try
        {
            var response = await _retryPolicy.ExecuteAsync(
                async (ctx, ct) =>
                {
                    var request = new HttpRequestMessage(HttpMethod.Post,
                        "https://ncpdp-gateway.gainwell.com/v1/transactions");

                    request.Content = JsonContent.Create(transaction);
                    request.Headers.Add("X-Idempotency-Key", idempotencyKey);
                    request.Headers.Add("X-Transaction-Id", transaction.TransactionId.ToString());

                    return await _httpClient.SendAsync(request, ct);
                },
                context,
                cts.Token);

            response.EnsureSuccessStatusCode();

            var ncpdpResponse = await response.Content.ReadFromJsonAsync<NcpdpResponse>(
                cancellationToken: cancellationToken);

            // Cache response with 24-hour TTL for idempotency
            await CacheResponseAsync(idempotencyKey, ncpdpResponse, cancellationToken);

            _logger.LogInformation(
                "NCPDP transaction {TransactionId} completed in {DurationMs}ms. " +
                "Copay: ${Copay}, AuthorizationCode: {AuthCode}",
                transaction.TransactionId,
                stopwatch.ElapsedMilliseconds,
                ncpdpResponse.PatientPayAmount,
                ncpdpResponse.AuthorizationNumber);

            return ncpdpResponse;
        }
        catch (OperationCanceledException) when (cts.IsCancellationRequested)
        {
            _logger.LogError(
                "NCPDP transaction {TransactionId} timed out after {DurationMs}ms (8s timeout)",
                transaction.TransactionId,
                stopwatch.ElapsedMilliseconds);

            throw new TransactionTimeoutException(
                $"Transaction exceeded 8-second timeout after {3} retry attempts");
        }
    }

    private string GenerateIdempotencyKey(NcpdpTransaction transaction)
    {
        // Format: ncpdp:{PrescriptionNumber}:{DispenseDate}:{PharmacyNPI}
        return $"ncpdp:{transaction.PrescriptionNumber}:{transaction.DateOfService:yyyyMMdd}:{transaction.PharmacyNpi}";
    }
}
